// Se identifica la línea del pedido que corresponde al producto
// que el usuario acaba de seleccionar (guardado en USUARIOS como
// 'producto_actual'). Si ese producto TODAVÍA NO tiene fila en
// SESSIONS (primera vez que se agrega en este pedido), se arma una
// línea en blanco con cantidad 0 para ESE producto — nunca se debe
// reusar por accidente la fila de otro producto distinto.
const productoActual = $('Get row(s) in sheet').item.json.producto_actual;
const pendiente = items.find(item => String(item.json.id_producto) === String(productoActual));

const base = pendiente ? pendiente.json : { id_producto: productoActual, cantidad: 0 };

return [
  { json: base }
];

